ctx_vue <- function(b, arrete) {
  ctx <- ns$.contexte(b, d, list(date_extraction = A), arrete)
  ns$.initialiser_visibilite(ctx); ns$.regle_prealable(ctx); ns$.construire_vue(ctx)
  ctx
}
