r <- cb(avec(function(b) { b$garanties_souscrites$date_effet[3L] <- D("2025-06-01"); b$garanties_souscrites$code_garantie[3L] <- "zzz"; b }))
x <- r$enjeu[r$enjeu$motif == "D10b" & r$enjeu$famille == "engagement", ]
