                   ensembles(c(c(D07a = "H;S", D07b = "X;S", D07c = "H;S"), a5e_sous_cas_d10, c(D11a = "X;S", D11b = "X;S", D11c = "X;S"))),
                   c("D07", "D10", "D11")))
