              c(vapply(ns$.motifs_signalement(d), function(m) valider(list(hypotheses = hyp2(m, valeur = "signalement"))), ""),
                valider(list(hypotheses = hyp2("D10f"), exclusions = rbind(excl4("D10b"), excl4("D10e"))))),
