d01a <- function(t, i, f = identity) {
  x <- cb(avec(function(b) { b[[t]] <- rbind(b[[t]], f(b[[t]][i, ])); b }))$enjeu
  x <- x[x$motif == "D01a" & x$table %in% t & x$garantie == "ensemble", ]
  paste(x$composante, x$unite, x$montant, x$cause)
}
