# lignes de l'écart D01a dont les doubles divergent (.divergences_d01a()) : identifiants
# regroupés à l'égalité exacte de chaque composante de clé, un « NA » littéral distinct de
# l'absence (#121 (iii)). Cas sur une composante dont l'absence est une valeur (#143, v1.8 :
# parametres.categorie_invalidite ; une absence d'identifiant n'entre plus dans l'écart D01a) :
# la ligne 1 de parametres (GS1, taux_capital, sans catégorie), sa copie (ligne 9, sans catégorie)
# et une seconde copie (ligne 10), de catégorie absente ou littérale « NA », ces lignes portant
# les valeurs `valeurs` ; lignes de l'écart lues dans le placement de la vue (celles du bilan)
divergences_131 <- function(valeurs, categorie) {
  b <- avec(function(b) { p <- b$parametres; b$parametres <- rbind(p, p[1L, ], p[1L, ])
                          n <- nrow(b$parametres); b$parametres$valeur[c(1L, n - 1L, n)] <- valeurs
                          b$parametres$categorie_invalidite[n] <- categorie; b })
  v <- ns$vue_a_date(b, A, NULL, NULL)
  ecart <- Filter(function(e) e$table == "parametres" && e$motif == "D01a", v$ctx$placement$ecarts)
  list(ecart = ecart[[1L]]$lignes, divergentes = ns$.divergences_d01a(v$ctx, "parametres", ecart[[1L]]$lignes, "valeur"))
}
verifier_egal("#131, #143 : .divergences_d01a() sur l'écart D01a de parametres : la copie de catégorie littérale « NA » (ligne 10) n'est pas regroupée avec les lignes de catégorie absente (1 et 9) : valeurs concordantes (2, 2) : aucune divergence ; valeur divergente (2, 5) : lignes 1 et 9 seulement",
              list(divergences_131(c(2, 2, 3), "NA"), divergences_131(c(2, 5, 3), "NA")),
              list(list(ecart = 9L, divergentes = integer(0)), list(ecart = 9L, divergentes = c(1L, 9L))))
verifier_egal("#131, #143 : .divergences_d01a(), témoin : la copie de catégorie absente (ligne 10) est regroupée avec les lignes 1 et 9 : deux lignes d'écart, divergence (2, 2, 3) sur les trois",
              divergences_131(c(2, 2, 3), NA_character_), list(ecart = 9:10, divergentes = c(1L, 9L, 10L)))
# rattachement d'une affiliation par une garantie souscrite en double (#131, Q3 d'`actuary`) :
# lecture existentielle sur les occurrences ; une copie de GS1 (ou GS2) sur CT2 rend le
# rattachement des dossiers non déterminé (nombre_dossiers NA de l'écart d'affiliations), dans les
# deux ordres ; témoin : une copie à l'identique (CT1) rattache (3 dossiers)
ratt_131 <- function(k, contrat) {
  b <- avec(function(b) {
    b$garanties_souscrites <- rbind(b$garanties_souscrites, transform(b$garanties_souscrites[k, ], id_contrat = contrat)); b })
  r <- list(controler_base(b, A), controler_base(inverser_lignes(b), A))
  list(identique = identical(r[[1L]], r[[2L]]),
       nombre_dossiers = vapply(r, function(x) refus(x, "refus_induit", "affiliations")$nombre_dossiers, 0L))
}
verifier_egal("#131, rattachement d'affiliations, copie de GS1 sur CT2 : bilan identique dans les deux ordres, nombre_dossiers de l'écart d'affiliations NA",
              ratt_131(1L, "CT2"), list(identique = TRUE, nombre_dossiers = c(NA_integer_, NA_integer_)))
verifier_egal("#131, rattachement d'affiliations, copie de GS2 sur CT2 : bilan identique, nombre_dossiers NA ; témoin, copie de GS2 à l'identique (CT1) : 3 dossiers dans les deux ordres",
              list(ratt_131(2L, "CT2"), ratt_131(2L, "CT1")),
              list(list(identique = TRUE, nombre_dossiers = c(NA_integer_, NA_integer_)),
                   list(identique = TRUE, nombre_dossiers = c(3L, 3L))))
# affiliation d'id_contrat manquant : une clé manquante ne s'apparie à aucune ligne, aucune
# paire (0 dossier), seule ou avec GS1 en double (sur CT2), dans les deux ordres
ratt_na_131 <- function(double) {
  b <- avec(function(b) {
    # copie sur le contrat individuel CT2 : maintien_deces manquant (hors condition, dictionnaire 1.6)
    if (double) b$garanties_souscrites <- rbind(b$garanties_souscrites, transform(b$garanties_souscrites[1L, ], id_contrat = "CT2",
                                                                                  maintien_deces = NA))
    b$affiliations$id_contrat[1L] <- NA
    b
  })
  r <- tryCatch(list(controler_base(b, A), controler_base(inverser_lignes(b), A)), error = function(e) conditionMessage(e))
  if (is.character(r)) return(r)
  x <- r[[1L]]$refus_tables
  list(identique = identical(r[[1L]], r[[2L]]),
       nombre_dossiers = stats::setNames(x$nombre_dossiers[x$table == "affiliations"], x$motif[x$table == "affiliations"]))
}
verifier_egal("#131, rattachement d'une affiliation d'id_contrat manquant : bilan rendu, 0 dossier ; avec GS1 en double (CT2) : 0 dossier ; dans les deux ordres",
              list(ratt_na_131(FALSE), ratt_na_131(TRUE)),
              list(list(identique = TRUE, nombre_dossiers = c(manquant_obligatoire = 0L)),
                   list(identique = TRUE, nombre_dossiers = c(refus_induit = 0L, manquant_obligatoire = 0L))))
# .verdict3() : lignes à domaine propre regroupées sur une clé injective (constat d'`audit`) :
# séparateurs dans une valeur, NA contre NaN ; verdict de chaque ligne égal à celui de la ligne
# seule
e_sep <- list(tc = "sinistres.id_assure", valeurs = c(NA, NA), inconnu = c(TRUE, TRUE), index = NULL, domaine = NULL,
              domaines = list(c("a\002=b", "c"), c("a", "b\002=c")), d01a = c(TRUE, TRUE))
e_nan <- list(tc = "t.x", valeurs = c(NA, NA), inconnu = c(TRUE, TRUE), index = NULL, domaine = NULL,
              domaines = list(c(NaN, 1), c(NA, 1)), d01a = c(TRUE, TRUE))
verifier_egal("#131, .verdict3(), domaines propres : clé injective (séparateurs dans une chaîne ; NA et NaN distincts) : TRUE puis NA ; FALSE puis NA",
              list(as.vector(ns$.verdict3(list(assure = e_sep, local = ns$.connue3("famille.id_assure", c("a", "a"))),
                                          function(x) !is.na(x$assure) & x$assure != x$local)),
                   as.vector(ns$.verdict3(list(x = e_nan), function(x) x$x %in% NA_real_))),
              list(c(TRUE, NA), c(FALSE, NA)))
# bout en bout : SI1 et SI2 en double, assurés « a\002=b » ou « c », « a » ou « b\002=c » ;
# famille de l'assuré « a » sur chacun : même bilan dans les deux ordres
b <- avec(function(b) {
  s <- b$sinistres
  b$sinistres <- rbind(transform(s[1L, ], id_assure = "a\002=b"), transform(s[1L, ], id_assure = "c"),
                       transform(s[2L, ], id_assure = "a"), transform(s[2L, ], id_assure = "b\002=c"))
  f <- b$famille[c(1L, 1L), ]
  f$id_sinistre <- c("SI1", "SI2")
  f$id_assure <- "a"
  b$famille <- f
  b
})
verifier("#131, .verdict3(), domaines propres à séparateurs : bilan identique dans les deux ordres",
         identical(controler_base(b, A), controler_base(inverser_lignes(b), A)))
# #146 : clé injective des domaines propres quels que soient la locale et le marquage des chaînes
# (octets de chaque texte ; seules les chaînes marquées latin1 sont converties en UTF-8 ; marque
# U / S / B selon l'encodage déclaré, sans lire la locale) :
# (a) « ééé S4: » marqué latin1 et « b » contre « ééé » et « S1:b » (sous une locale UTF-8, paste0()
# traduit le latin1 et la longueur annoncée ne couvre plus le texte inscrit) ; (b) « é » en octets
# UTF-8 sans marque contre le texte « <c3><a9> » (sous une locale non UTF-8, enc2utf8() réécrirait
# la première en échappements identiques à la seconde) ; (c) « é » marqué bytes contre « é » unknown
# de mêmes octets (R les tient pour différentes, `==` FALSE : clés distinctes, marques B et U) ;
# (d) mêmes octets, « é » unknown contre « é » marqué UTF-8 : R les tient pour différentes sous
# LC_ALL=C (`==` FALSE, marques U et S, clés distinctes, verdicts TRUE NA ; NA TRUE) et pour égales
# sous LC_ALL=C.UTF-8 (`==` TRUE : le verdict est celui de deux domaines égaux, NA NA, que donne le
# cas (e), « é » UTF-8 dans les deux domaines ; les deux clés distinctes ne font que découper
# les lignes en deux groupes essayés séparément). Chaque cas dans un sous-processus R, sous
# LC_ALL=C et sous LC_ALL=C.UTF-8, sur le package installé par la batterie : verdicts de .verdict3()
# dans les deux ordres des domaines, avec un prédicat où chaque domaine a un verdict distinct
# (A : NA, B : TRUE).
verdicts_146 <- function(locale) {
  script <- tempfile(fileext = ".R")
  writeLines(c(
    sprintf(".libPaths(c(%s, .libPaths()))", deparse(dirname(find.package("provie")))),
    'ns <- asNamespace("provie")',
    'ent <- function(doms) list(tc = "t.x", valeurs = c(NA, NA), inconnu = c(TRUE, TRUE), index = NULL, domaine = NULL,',
    '                           domaines = doms, d01a = c(TRUE, TRUE))',
    'p <- function(x) !is.na(x$assure) & x$assure != x$local',
    'v <- function(a, b, loc) {',
    '  l <- ns$.connue3("famille.id_assure", c(loc, loc))',
    '  c(as.vector(ns$.verdict3(list(assure = ent(list(a, b)), local = l), p)),',
    '    as.vector(ns$.verdict3(list(assure = ent(list(b, a)), local = l), p)))',
    '}',
    'lat <- iconv("\\u00e9\\u00e9\\u00e9S4:", "UTF-8", "latin1")',
    'o <- rawToChar(as.raw(c(0xc3, 0xa9)))',
    'u <- o; Encoding(u) <- "UTF-8"',
    'by <- o; Encoding(by) <- "bytes"',
    'cat(Sys.getlocale("LC_CTYPE"), Encoding(lat), Encoding(o), Encoding(u), o == u,',
    '    v(c(lat, "b"), c("\\u00e9\\u00e9\\u00e9", "S1:b"), "b"), v(c(o, "b"), c("<c3><a9>", "b"), o),',
    '    v(c(by, "b"), c(o, "b"), o), v(c(o, "b"), c(u, "b"), u), v(c(u, "b"), c(u, "b"), u), sep = "|")'),
    script)
  sortie <- suppressWarnings(system2(file.path(R.home("bin"), "Rscript"), c("--vanilla", shQuote(script)),
                                     stdout = TRUE, stderr = FALSE, env = paste0("LC_ALL=", locale)))
  unlink(script)
  if (length(sortie) == 0L) return(character(0))
  strsplit(utils::tail(sortie, 1L), "|", fixed = TRUE)[[1L]]
}
v_c <- verdicts_146("C")
v_u <- verdicts_146("C.UTF-8")
# cas (a) à (c) et témoin (e) : mêmes verdicts sous les deux locales ; cas (d) : TRUE NA ; NA TRUE
# sous C (o != u), NA NA ; NA NA sous C.UTF-8 (o == u, comme le cas (e))
v_abc <- c("NA", "TRUE", "TRUE", "NA", "NA", "TRUE", "TRUE", "NA", "TRUE", "NA", "NA", "TRUE")
verifier("#146, .verdict3(), clé injective sous LC_ALL=C et LC_ALL=C.UTF-8 (deux processus R) : latin1 contre UTF-8, octets sans marque contre échappements littéraux, bytes contre unknown, unknown contre UTF-8 (égales pour R sous C.UTF-8, différentes sous C), dans les deux ordres des domaines ; chaînes bien marquées latin1, unknown et UTF-8",
         length(v_c) == 25L && length(v_u) == 25L && v_c[1L] == "C" && grepl("utf-?8", v_u[1L], ignore.case = TRUE) &&
           identical(v_c[2:4], c("latin1", "unknown", "UTF-8")) && identical(v_u[2:4], c("latin1", "unknown", "UTF-8")) &&
           identical(v_c[5L], "FALSE") && identical(v_u[5L], "TRUE") &&
           identical(v_c[6:17], v_abc) && identical(v_u[6:17], v_abc) &&
           identical(v_c[18:21], c("TRUE", "NA", "NA", "TRUE")) && identical(v_u[18:21], rep("NA", 4L)) &&
           identical(v_c[22:25], rep("NA", 4L)) && identical(v_u[22:25], rep("NA", 4L)))
# conversion des chaînes latin1 en UTF-8 dans la clé de découpage (code_valeurs() de .verdict3()) :
# le « é » latin1 et le « é » UTF-8 de deux domaines égaux sous LC_ALL=C.UTF-8 reçoivent la même
# clé (lignes essayées ensemble) : 2 appels du prédicat ; sans la conversion, deux clés distinctes :
# 3 appels (mesuré sur le mutant sans la ligne `x[lat] <- enc2utf8(x[lat])`). Le verdict est NA NA
# dans les deux cas, seul le nombre d'appels distingue le mutant. Sous-processus R forcé sous
# LC_ALL=C.UTF-8, sur le package installé par la batterie.
appels_146 <- function(locale) {
  script <- tempfile(fileext = ".R")
  writeLines(c(
    sprintf(".libPaths(c(%s, .libPaths()))", deparse(dirname(find.package("provie")))),
    'ns <- asNamespace("provie")',
    'ent <- function(doms) list(tc = "t.x", valeurs = c(NA, NA), inconnu = c(TRUE, TRUE), index = NULL, domaine = NULL,',
    '                           domaines = doms, d01a = c(TRUE, TRUE))',
    'appels <- 0L',
    'p <- function(x) { appels <<- appels + 1L; !is.na(x$assure) & x$assure != x$local }',
    'l1 <- iconv("\\u00e9", "UTF-8", "latin1")',
    'u1 <- "\\u00e9"',
    'r <- ns$.verdict3(list(assure = ent(list(c(l1, "b"), c(u1, "b"))), local = ns$.connue3("famille.id_assure", c("b", "b"))), p)',
    'cat(Sys.getlocale("LC_CTYPE"), Encoding(l1), Encoding(u1), l1 == u1, as.vector(r), appels, sep = "|")'),
    script)
  sortie <- suppressWarnings(system2(file.path(R.home("bin"), "Rscript"), c("--vanilla", shQuote(script)),
                                     stdout = TRUE, stderr = FALSE, env = paste0("LC_ALL=", locale)))
  unlink(script)
  if (length(sortie) == 0L) return(character(0))
  strsplit(utils::tail(sortie, 1L), "|", fixed = TRUE)[[1L]]
}
a_u <- appels_146("C.UTF-8")
verifier("#146, .verdict3(), conversion latin1 vers UTF-8 de la clé de découpage : « é » latin1 et « é » UTF-8 dans deux domaines égaux (sous LC_ALL=C.UTF-8, `==` TRUE), verdict NA NA, 2 appels du prédicat (3 sans la conversion)",
         length(a_u) == 7L && grepl("utf-?8", a_u[1L], ignore.case = TRUE) && identical(a_u[2:4], c("latin1", "UTF-8", "TRUE")) &&
           identical(a_u[5:6], c("NA", "NA")) && identical(a_u[7L], "2"))
# bout en bout (locale de la batterie) : SI1 et SI2 en double avec ces domaines, assuré « b » en
# famille ; bilan identique dans les deux ordres, latin1 comme UTF-8
b_enc <- function(latin1) avec(function(b) {
  s <- b$sinistres
  a1 <- "\u00e9\u00e9\u00e9S4:"
  if (latin1) a1 <- iconv(a1, "UTF-8", "latin1")
  b$sinistres <- rbind(transform(s[1L, ], id_assure = a1), transform(s[1L, ], id_assure = "b"),
                       transform(s[2L, ], id_assure = "\u00e9\u00e9\u00e9"), transform(s[2L, ], id_assure = "S1:b"))
  f <- b$famille[c(1L, 1L), ]
  f$id_sinistre <- c("SI1", "SI2")
  f$id_assure <- "b"
  b$famille <- f
  b
})
verifier_egal("#146, bout en bout : la colonne porte bien la marque latin1 (témoin), bilan identique dans les deux ordres, latin1 comme UTF-8",
              list(Encoding(b_enc(TRUE)$sinistres$id_assure[1L]),
                   identical(controler_base(b_enc(TRUE), A), controler_base(inverser_lignes(b_enc(TRUE)), A)),
                   identical(controler_base(b_enc(FALSE), A), controler_base(inverser_lignes(b_enc(FALSE)), A))),
              list("latin1", TRUE, TRUE))
