              list(ns$.rattacher(ctx_complet(b122_r, A), "evenements")$cause, grep("^[a-z_]+ dossiers id_sinistre", ne122(cb(b122_r)), value = TRUE),
                   identical(cb(b122_r), sans_requises_hors_constat(env122r$controler_base(b122_r, A)))),
