              list(pa_m704("contrats", "date_effet", 1L, rep("conserver", 4L)), pa_m704("prestations", "date_reglement", 2L, rep("conserver", 4L)),
                   pa_m704("garanties_souscrites", "date_effet", 1L, rep("conserver", 4L)), pa_m704("cotisations", "date_mouvement", 1L, rep("conserver", 4L)),
                   pa_m704("garanties_souscrites", "date_effet", 1L, rep("exclure", 4L)),
                   pa_m704("garanties_souscrites", "date_effet", 1L, c("exclure", "conserver", "conserver", "conserver"))),
              list(c(NA, "D03i", NA), c("D03i", NA, "D03i"), rep("D03i", 3L), c(NA, "D03i", NA), rep(NA_character_, 3L),
                   c(NA, "D03i", NA)))

# .garantie_en_vigueur3() : appariement des versions non déterminées par clé (P7 de la revue
# finale de Bdr-b1, #34). Oracle : ancienne forme, une boucle sur les éléments avec un which()
# sur toutes les versions non déterminées (coût éléments x versions non déterminées) ; la sortie
# doit lui être identique, sur un banc aléatoire (graine fixée : clés multiples, versions non
# déterminées multiples par clé, dates manquantes, éléments hors `lignes`, éléments déjà vrais).
# Depuis #153 (M613), la clé de .garantie_en_vigueur3() est une liste (contrat, collège) sans
# paste() ; l'oracle garde la clé composite de l'ancienne forme, égale sur le banc, où aucun
# collège ni aucun contrat de version n'est manquant (le traitement des composantes manquantes
# a ses tests propres, #153).
cle_ancienne <- function(cle, college) if (college) paste(cle$contrat, cle$college, sep = "\r") else as.character(cle$contrat)
gev3_ancien <- function(ctx, code, cle, survenance, lignes = rep(TRUE, length(survenance)), college = TRUE) {
  cle <- cle_ancienne(cle, college)
  v <- function(c1) ns$.valeurs(ctx, "garanties_souscrites", c1)
  cle_de <- function(k) if (college) paste(v("id_contrat")[k], v("college")[k], sep = "\r") else as.character(v("id_contrat")[k])
  versions <- which(ns$.valeurs_vue(ctx, "garanties_souscrites", "code_garantie") %in% code)
  cle_v <- cle_de(versions)
  effet <- as.numeric(v("date_effet"))[versions]
  fin <- as.numeric(v("date_fin"))[versions]
  par_cle <- split(seq_along(cle_v), factor(cle_v, levels = unique(cle_v)))
  trouvees <- lapply(seq_along(cle), function(i) {
    j <- if (is.na(cle[i])) NULL else par_cle[[cle[i]]]
    if (is.na(survenance[i]) || length(j) == 0L) return(integer(0))
    versions[j[!is.na(effet[j]) & effet[j] <= survenance[i] & (is.na(fin[j]) | fin[j] >= survenance[i])]]
  })
  valeurs <- lengths(trouvees) > 0L
  nd <- ns$.nd_vue(ctx, "garanties_souscrites")
  index <- vector("list", length(cle))
  trouvees_nd <- vector("list", length(cle))
  if (any(nd)) {
    versions_nd <- which(nd & v("code_garantie") %in% code)
    cle_nd <- cle_de(versions_nd)
    effet_nd <- as.numeric(v("date_effet"))[versions_nd]
    fin_nd <- as.numeric(v("date_fin"))[versions_nd]
    for (i in which(lignes & !is.na(survenance))) {
      j <- which(cle_nd == cle[i] & !is.na(effet_nd) & effet_nd <= survenance[i] & (is.na(fin_nd) | fin_nd >= survenance[i]))
      if (length(j) > 0L) {
        trouvees_nd[[i]] <- versions_nd[j]
        if (!valeurs[i]) index[[i]] <- versions_nd[j]
      }
    }
  }
  list(tc = "garanties_souscrites", valeurs = valeurs, inconnu = lengths(index) > 0L, index = index, domaine = c(TRUE, FALSE),
       versions = trouvees, versions_nd = trouvees_nd)
}
# contexte minimal : vue à un arrêté antérieur à l'extraction (visibilité déposée, `statut` NA :
# version non déterminée), `n_v` versions de garanties_souscrites, `n_c` contrats, 3 collèges
gev3_ctx <- function(n_v, n_c, n_e) {
  gs <- data.frame(id_contrat = sprintf("K%03d", sample.int(n_c, n_v, TRUE)),
                   college = sample(c("C1", "C2", "C3"), n_v, TRUE),
                   code_garantie = sample(c("deces", "invalidite"), n_v, TRUE, c(0.7, 0.3)),
                   date_effet = as.Date("2020-01-01") + sample(c(0:2000, NA), n_v, TRUE),
                   date_fin = as.Date("2020-01-01") + sample(c(0:3000, NA, NA), n_v, TRUE), stringsAsFactors = FALSE)
  ctx <- new.env()
  ctx$base <- list(garanties_souscrites = gs)
  ctx$retenu <- list(garanties_souscrites = sample(c(TRUE, FALSE), n_v, TRUE, c(0.6, 0.4)))
  ctx$date_extraction <- D("2026-12-31"); ctx$arrete <- D("2025-12-31")
  ctx$visibilite_vue <- list(statut = list(garanties_souscrites = ifelse(ctx$retenu$garanties_souscrites, TRUE,
                                                                          sample(c(NA, FALSE), n_v, TRUE, c(0.7, 0.3)))))
  ctx
}
set.seed(34)
ecarts_gev3 <- vapply(seq_len(200L), function(k) {
  n_c <- sample(c(1L, 3L, 12L), 1L)
  ctx <- gev3_ctx(sample(1:60, 1L), n_c, 0L)
  n_e <- sample(1:40, 1L)
  college <- sample(c(TRUE, FALSE), 1L)
  gs <- ctx$base$garanties_souscrites
  cle <- list(contrat = sprintf("K%03d", sample.int(n_c + 1L, n_e, TRUE)), college = sample(c("C1", "C2", "C3", NA), n_e, TRUE))
  cle$contrat[sample.int(n_e, 1L)] <- NA
  surv <- as.numeric(as.Date("2020-01-01") + sample(c(-200:3200, NA), n_e, TRUE))
  lignes <- sample(c(TRUE, FALSE), n_e, TRUE, c(0.8, 0.2))
  code <- sample(list("deces", "invalidite", c("deces", "invalidite")), 1L)[[1L]]
  !identical(ns$.garantie_en_vigueur3(ctx, code, cle, surv, lignes, college), gev3_ancien(ctx, code, cle, surv, lignes, college))
}, TRUE)
verifier("garantie_en_vigueur3 : sortie identique à l'ancienne forme (boucle par élément) sur 200 tirages (clés multiples, versions non déterminées multiples par clé, dates manquantes, éléments hors lignes)",
         !any(ecarts_gev3))
verifier("garantie_en_vigueur3 : le banc contient des versions non déterminées appariées (au moins un élément inconnu et un élément vrai portant des versions_nd)",
         {
           set.seed(35)
           ctx <- gev3_ctx(60L, 3L, 0L)
           cle <- list(contrat = sprintf("K%03d", sample.int(3L, 40L, TRUE)), college = sample(c("C1", "C2", "C3"), 40L, TRUE))
           r <- ns$.garantie_en_vigueur3(ctx, "deces", cle, as.numeric(as.Date("2020-01-01")) + sample(0:3000, 40L, TRUE))
           any(r$inconnu) && any(r$valeurs & lengths(r$versions_nd) > 0L)
         })
# travail de .garantie_en_vigueur3 : travail_de() de tests/harnais.R ; ops = which et opérations
# vectorielles que l'ancienne forme applique à toutes les versions non déterminées pour chaque
# élément (`[` exclu : l'extraction d'un élément `x[i]` est faite en temps constant) ; `.paires`
# (sous) est la fonction d'appariement de la nouvelle forme
OPS_GEV3 <- c("which", "==", "<=", ">=", "&", "|", "!", "is.na", "match", "unique", "order", "rep", "c")
travail_gev3 <- function(f, n, sous = character(0)) {
  set.seed(36)
  ctx <- gev3_ctx(n, n, 0L)
  ctx$retenu$garanties_souscrites[] <- FALSE; ctx$visibilite_vue$statut$garanties_souscrites[] <- NA
  ctx$base$garanties_souscrites$code_garantie <- "deces"
  cle <- list(contrat = sprintf("K%03d", sample.int(n, n, TRUE)), college = sample(c("C1", "C2", "C3"), n, TRUE))
  travail_de(f, ctx, "deces", cle, as.numeric(as.Date("2020-01-01")) + sample(0:3000, n, TRUE), ops = OPS_GEV3, sous = sous)
}
travail_gev3_nouveau <- vapply(c(500L, 2000L), function(n) travail_gev3(ns$.garantie_en_vigueur3, n, sous = ".paires"), 0)
travail_gev3_ancien <- vapply(c(500L, 2000L), function(n) travail_gev3(gev3_ancien, n), 0)
verifier("performance : travail de .garantie_en_vigueur3 de 500 à 2 000 éléments et versions non déterminées multiplié par moins de 6 (linéaire : 4 ; boucle par élément : 16 ; P7, #34)",
         travail_gev3_nouveau[2L] / travail_gev3_nouveau[1L] < 6)
verifier("performance : la mesure détecte l'ancienne forme (travail de la boucle par élément multiplié par plus de 10 sur les mêmes tailles)",
         travail_gev3_ancien[2L] / travail_gev3_ancien[1L] > 10)

# #153 (spécification `donnees` v1.8, M613 ; critères C153-1 à C153-5) : clés composites sans
# paste(). Une composante manquante ou vide ne s'apparie à rien, ni à une autre composante
# manquante, ni au « NA » littéral. Cas latents (aucune base ne les amène aux sites, M169) :
# appels internes de .garantie_en_vigueur3() et de .composantes_dossiers().
# Contexte minimal de .garantie_en_vigueur3() : versions de garanties_souscrites données, `retenu`
# (TRUE : retenue ; FALSE : de visibilité non déterminée, à un arrêté antérieur à l'extraction)
gev3_ctx_gs <- function(contrat, college, retenu = rep(TRUE, length(contrat))) {
  n <- length(contrat)
  ctx <- new.env()
  ctx$base <- list(garanties_souscrites = data.frame(id_contrat = contrat, college = college, code_garantie = "deces",
                                                     date_effet = D("2020-01-01"), date_fin = D(NA), stringsAsFactors = FALSE))
  ctx$retenu <- list(garanties_souscrites = retenu)
  ctx$date_extraction <- D("2026-12-31"); ctx$arrete <- D("2025-12-31")
  ctx$visibilite_vue <- list(statut = list(garanties_souscrites = ifelse(retenu, TRUE, NA)))
  ctx
}
surv153 <- as.numeric(D("2024-06-01"))
gev153 <- function(ctx, contrat, college = rep("C1", length(contrat)), ...)
  ns$.garantie_en_vigueur3(ctx, "deces", list(contrat = contrat, college = college), rep(surv153, length(contrat)), ...)
# C153-1 : contrat manquant ou vide des deux côtés (versions retenues, puis non déterminées)
for (retenu in c(TRUE, FALSE)) {
  r <- gev153(gev3_ctx_gs(c(NA, "", "K1"), "C1", rep(retenu, 3L)), c(NA, "", "K1", "K2"))
  verifier_egal(paste0("#153, C153-1 : contrat manquant ou vide des deux côtés (versions ", if (retenu) "retenues" else "non déterminées",
                       ") : aucune version appariée ; K1 apparié ; K2 sans version (avant #153 : NA et \"\" appariés à eux-mêmes par paste())"),
                list(r$valeurs, r$inconnu, lengths(r$versions), lengths(r$versions_nd)),
                if (retenu) list(c(FALSE, FALSE, TRUE, FALSE), c(FALSE, FALSE, FALSE, FALSE), c(0L, 0L, 1L, 0L), c(0L, 0L, 0L, 0L))
                else list(c(FALSE, FALSE, FALSE, FALSE), c(FALSE, FALSE, TRUE, FALSE), c(0L, 0L, 0L, 0L), c(0L, 0L, 1L, 0L)))
}
# C153-4 : témoin, collège « NA » littéral des deux côtés apparié, et lui seul ; collège manquant
# d'un élément (affiliation d'un contrat individuel, colonne `college` NA) apparié à rien
for (retenu in c(TRUE, FALSE)) {
  r <- gev153(gev3_ctx_gs(c("K1", "K1"), c("NA", "C2"), rep(retenu, 2L)), rep("K1", 5L), c("NA", NA, "", "C2", "C3"))
  verifier_egal(paste0("#153, C153-4 : collège « NA » littéral apparié au « NA » littéral seul (versions ", if (retenu) "retenues" else "non déterminées",
                       ") ; collège manquant ou vide de l'élément : aucun appariement ; autre collège : le sien (avant #153 : NA apparié au « NA » littéral)"),
                if (retenu) r$valeurs else r$inconnu, c(TRUE, FALSE, FALSE, TRUE, FALSE))
}
# C153-2 : collège refusé de garanties_souscrites lu : erreur interne, aucun verdict (Q-B3 (ii)) ;
# contexte réel, après les règles B et P (le refus est lu par .cause_lecture(), comme par .regle_vue())
gev153_refus <- function(college_refuse) {
  b <- base_ref
  b$garanties_souscrites$college[1L] <- college_refuse
  ctx <- ns$.contexte(b, d, list(date_extraction = A), A)
  ctx$declarations <- ns$lire_declarations(NULL, d)
  ctx$conventions <- ns$.lire_conventions(NULL)
  ns$.regle_forme(ctx); ns$.regle_domaine(ctx); ns$.regle_cles(ctx); ns$.refus_induits(ctx); ns$.refus_regle_b(ctx)
  ns$.regle_p(ctx); ns$.construire_vue(ctx)
  ctx
}
message153 <- function(expr) tryCatch({ expr; "aucune erreur" }, error = function(e) conditionMessage(e))
for (refuse in list(NA_character_, "")) {
  ctx <- gev153_refus(refuse)
  for (college_el in c("NA", "ensemble", NA)) {
    verifier(paste0("#153, C153-2 : garanties_souscrites.college ", if (is.na(refuse)) "manquant" else "vide", " lu face au collège ",
                    if (is.na(college_el)) "manquant" else paste0("« ", college_el, " »"), " : erreur interne, aucun verdict"),
             grepl("^erreur interne de provie : \\.garantie_en_vigueur3\\(\\) lit garanties_souscrites\\.college", message153(gev153(ctx, "CT1", college_el))))
  }
  verifier(paste0("#153, C153-2 : la même lecture sans le collège (college = FALSE) ne lit pas la colonne refusée : aucune erreur, contrat CT1 en vigueur"),
           identical(ns$.garantie_en_vigueur3(ctx, "deces", list(contrat = "CT1"), surv153, college = FALSE)$valeurs, TRUE))
}
verifier("#153, C153-2 : témoin, collège renseigné partout : aucune erreur, garantie decès de CT1, collège « ensemble », en vigueur",
         identical(gev153(gev153_refus("ensemble"), "CT1", "ensemble")$valeurs, TRUE))
# Clé mal formée : aucun recyclage silencieux de la clé (composante absente ou de longueur différente de survenance)
ctx153_cle <- gev3_ctx_gs("K1", "C1")
for (cas in list(list(nom = "collège absent", cle = list(contrat = c("K1", "K1")), college = TRUE),
                 list(nom = "collège plus court", cle = list(contrat = c("K1", "K1"), college = "C1"), college = TRUE),
                 list(nom = "contrat plus court", cle = list(contrat = "K1", college = c("C1", "C1")), college = TRUE),
                 list(nom = "contrat absent (college = FALSE)", cle = list(), college = FALSE))) {
  verifier(paste0("#153 : clé de .garantie_en_vigueur3() mal formée (", cas$nom, ") : erreur interne, aucun recyclage"),
           grepl("^erreur interne de provie : \\.garantie_en_vigueur3\\(\\) : cl", message153(
             ns$.garantie_en_vigueur3(ctx153_cle, "deces", cas$cle, rep(surv153, 2L), college = cas$college))))
}
verifier("#153 : clé de longueur égale à celle de survenance : aucune erreur",
         identical(ns$.garantie_en_vigueur3(ctx153_cle, "deces", list(contrat = c("K1", "K1"), college = c("C1", "C1")), rep(surv153, 2L))$valeurs, c(TRUE, TRUE)))
# C153-3 : distinctes() de .composantes_dossiers(), paiements cumulés par dossier, un identifiant
# (clé primaire) compté une fois par dossier ; ids de prestations altérés après la construction
# de la vue (un identifiant manquant ou vide refuse la table, aucune base n'amène à ce site)
paie153 <- function(id, montant = c(100, 10, 1)[seq_along(id)]) {
  ctx <- ns$.contexte(base_ref, d, list(date_extraction = A), A)
  ns$.refus_regle_b(ctx); ns$.initialiser_visibilite(ctx); ns$.regle_prealable(ctx); ns$.construire_vue(ctx)
  ctx$base$prestations$id_prestation <- c(id, rep("PRZ", 3L - length(id)))
  ctx$base$prestations$id_dossier <- "DO1"
  ctx$base$prestations$montant <- c(montant, rep(0, 3L - length(montant)))
  ns$.composantes_dossiers(ctx)$valeurs$paiements_cumules[1L]
}
verifier_egal("#153, C153-3 : distinctes() : identifiants NA puis « NA » littéral d'un même dossier, les deux ordres : les deux lignes comptées (100 + 10) ; deux « NA » littéraux identiques : une fois ; deux manquants : deux fois ; deux vides : deux fois ; deux « PR » identiques : une fois (avant #153 : « NA » littéral et \"\" regroupés par paste())",
              list(paie153(c(NA, "NA")), paie153(c("NA", NA)), paie153(c("NA", "NA")), paie153(c(NA, NA)), paie153(c("", "")), paie153(c("PR", "PR")),
                   paie153(c("PR", NA, "NA"))),
              list(110, 110, 100, 110, 110, 100, 111))

section("donnees : #72, portée ligne d'un refus de valeur : enjeu par porteur (spécification v1.9, § 9.2 ; erratum du projet de dictionnaire 1.6, § 2 et § 11.5)")

# Une composante de l'enjeu n'est NA (cause = motif du refus) que pour le porteur qui lit une
# valeur refusée de portée ligne (ligne refusée rattachée à lui), et non plus dès qu'elle lit la
# colonne (avant #72 : composante empêchée pour tout porteur, cause la plus petite des refus de
# la colonne). Rangées « garantie composante unité montant cause ».
en72 <- function(r, motif, composante = NULL, table = NULL) {
  e <- r$enjeu[r$enjeu$motif %in% motif & (if (is.null(composante)) TRUE else r$enjeu$composante %in% composante) &
                 (if (is.null(table)) TRUE else r$enjeu$table %in% table), , drop = FALSE]
  paste(e$garantie, e$composante, e$unite, e$montant, e$cause)
}
cne72 <- function(r, code) { x <- ligne(r$controles_non_executes, code); paste(x$table, x$colonne, x$cause) }
# (a) D09 sur PR1 (indemnité journalière de DO3) et montant nul sur PR2 (capital de DO1,
# hors_domaine) : chaque écart lit sa seule ligne refusée, de son propre motif (avant #72 :
# hors_domaine pour les deux, plus petit des refus de la colonne) ; rangée ensemble des deux
r72a <- cb(avec(function(b) { b$prestations$montant[1:2] <- c(-1240, 0); b }))
verifier_egal("#72, enjeu (a) : D09 (PR1) et hors_domaine (PR2) sur prestations.montant : rangées D09 de cause D09, rangées hors_domaine de cause hors_domaine ; rangées ensemble : incapacite D09, deces et ensemble hors_domaine",
              list(en72(r72a, "D09"), en72(r72a, "hors_domaine"), en72(r72a, "ensemble")),
              list(c("incapacite prestations_ecartees euro NA D09", "ensemble prestations_ecartees euro NA D09"),
                   c("deces prestations_ecartees euro NA hors_domaine", "ensemble prestations_ecartees euro NA hors_domaine"),
                   c("deces prestations_ecartees euro NA hors_domaine", "incapacite prestations_ecartees euro NA D09",
                     "ensemble prestations_ecartees euro NA hors_domaine")))
# (b) écart hors_domaine sur sinistres.canal_declaration de SI1 (dossiers DO1, DO2) et D09 sur PR1
# (dossier DO3, d'un autre sinistre) : paiements_cumules de DO1 (60 000) et DO2 (750) calculés
# (avant #72 : NA, cause D09, et ligne (paiements_cumules, prestations, montant) dans
# controles_non_executes) ; D09 sur PR2 (dossier DO1) : paiements_cumules de DO1 NA (D09), DO2
# calculé, capital_fixe de DO1 calculé (60 000)
r72b <- cb(avec(function(b) { b$sinistres$canal_declaration[1L] <- "pigeon"; b$prestations$montant[1L] <- -1240; b }))
r72b2 <- cb(avec(function(b) { b$sinistres$canal_declaration[1L] <- "pigeon"; b$prestations$montant[2L] <- -60000; b }))
verifier_egal("#72, enjeu (b) : écart sur SI1, D09 sur PR1 (DO3) : paiements_cumules de DO1 et DO2 calculés (60 000, 750, ensemble 60 750), aucune ligne paiements_cumules non exécutée ; D09 sur PR2 (DO1) : DO1 NA (D09), DO2 750, capital_fixe deces 60 000",
              list(en72(r72b, "hors_domaine", "paiements_cumules"), cne72(r72b, "paiements_cumules"),
                   en72(r72b2, "hors_domaine", c("paiements_cumules", "capital_fixe")), cne72(r72b2, "paiements_cumules")),
              list(c("deces paiements_cumules euro 60000 NA", "rente_education paiements_cumules euro 750 NA",
                     "ensemble paiements_cumules euro 60750 NA"), character(0),
                   c("deces paiements_cumules euro NA D09", "deces capital_fixe euro 60000 NA", "rente_education paiements_cumules euro 750 NA",
                     "ensemble paiements_cumules euro NA D09", "ensemble capital_fixe euro 60000 NA"),
                   "prestations montant D09"))
# (c) code_garantie de GS3 (garantie de DO2) hors domaine : la garantie de DO2 est inconnue,
# non_rattache, ses composantes 2 à 4 sont sans valeur (cause hors_domaine) ; DO1 garde sa
# garantie deces (avant #72 : tous les dossiers non_rattache, composantes 2 à 4 empêchées)
r72c <- cb(avec(function(b) { b$sinistres$canal_declaration[1L] <- "pigeon"; b$garanties_souscrites$code_garantie[3L] <- "autre"; b }))
verifier_egal("#72, enjeu (c) : code_garantie de GS3 refusé : écart sur SI1 : DO1 deces (paiements_cumules et capital_fixe 60 000), DO2 non_rattache (paiements_cumules 750) ; composantes 2 à 4 de l'ensemble NA (hors_domaine)",
              en72(r72c, "hors_domaine", table = "sinistres"),
              c("deces paiements_cumules euro 60000 NA", "deces capital_fixe euro 60000 NA", "non_rattache paiements_cumules euro 750 NA",
                "ensemble paiements_cumules euro 60750 NA", "ensemble capital_fixe euro NA hors_domaine",
                "ensemble rente_annuelle_en_vigueur euro_par_an NA hors_domaine", "ensemble ij_en_vigueur euro_par_jour NA hors_domaine"))
# (d) evenements : écart hors_domaine sur justificatif de EV2 (service de DO3, 40 par jour) et
# D09 sur le montant de EV5 (service de RE1, -3 000 par an) : montant_evenement de EV2 calculé
# (avant #72 : NA, D09) ; celui de EV5 NA (D09) ; type_evenement de EV2 hors domaine : unité
# inconnue, montant_evenement NA dans les trois unités ; nature_mouvement de CO1 hors domaine :
# composante inconnue, cotisations émises et encaissées NA
r72d <- cb(avec(function(b) { b$evenements$justificatif[2L] <- "zzz"; b$evenements$montant[5L] <- -3000; b }))
r72e <- cb(avec(function(b) { b$evenements$type_evenement[2L] <- "zzz"; b }))
r72f <- cb(avec(function(b) { b$cotisations$nature_mouvement[1L] <- "zzz"; b }))
verifier_egal("#72, enjeu (d) : montant_evenement de EV2 (justificatif refusé) calculé, de EV5 (D09) NA, rente de DO2 (lue par EV5, service de RE1) NA ; type de EV2 refusé : NA dans les trois unités ; nature de CO1 refusée : cotisations émises et encaissées NA",
              list(en72(r72d, "hors_domaine", "montant_evenement"), en72(r72d, "D09", c("montant_evenement", "rente_annuelle_en_vigueur")),
                   en72(r72e, "hors_domaine", "montant_evenement"), en72(r72f, "hors_domaine")),
              list(c("incapacite montant_evenement euro_par_jour 40 NA", "ensemble montant_evenement euro 0 NA",
                     "ensemble montant_evenement euro_par_an 0 NA", "ensemble montant_evenement euro_par_jour 40 NA"),
                   c("rente_education rente_annuelle_en_vigueur euro_par_an NA D09", "rente_education montant_evenement euro_par_an NA D09",
                     "ensemble rente_annuelle_en_vigueur euro_par_an NA D09", "ensemble montant_evenement euro 0 NA",
                     "ensemble montant_evenement euro_par_an NA D09", "ensemble montant_evenement euro_par_jour 0 NA"),
                   c(paste("incapacite montant_evenement", c("euro", "euro_par_an", "euro_par_jour"), "NA hors_domaine"),
                     paste("ensemble montant_evenement", c("euro", "euro_par_an", "euro_par_jour"), "NA hors_domaine")),
                   paste(rep(c("deces", "ensemble"), each = 2L), c("cotisations_emises_nettes", "cotisations_encaissees"), "euro NA hors_domaine")))
# (e) rattachement d'une ligne refusée à une composante 1 à 4 par le type de l'événement : EV7,
# clôture de DO1 (dossier deces) au montant présent hors condition (hors_domaine), n'entre pas
# dans capital_fixe de DO1 (fixation seule) : 60 000 chiffré ; (f) sortie EV3 de SI2 de montant
# refusé, rattachée par le sinistre au dossier incapacite DO3 : ij_en_vigueur de DO3 sans valeur
r72g <- cb(avec(function(b) {
  b$sinistres$canal_declaration[1L] <- "pigeon"
  b$evenements <- rbind(b$evenements, transform(b$evenements[4L, ], id_evenement = "EV7", type_evenement = "cloture_dossier",
                                                motif = "regle", date_effet = D("2026-06-01"), date_saisie = D("2026-06-02"),
                                                montant = 5))
  b }))
r72h <- cb(avec(function(b) { b$sinistres$canal_declaration[2L] <- "pigeon"; b$evenements$montant[3L] <- -5; b }))
verifier_egal("#72, enjeu (e) et (f) : montant de la clôture EV7 de DO1 refusé : capital_fixe de DO1 chiffré (60 000) ; sortie EV3 de SI2 de montant refusé : ij_en_vigueur de DO3 sans valeur",
              list(en72(r72g, "hors_domaine", "capital_fixe", "sinistres"), en72(r72h, "hors_domaine", "ij_en_vigueur", "sinistres")),
              list(c("deces capital_fixe euro 60000 NA", "ensemble capital_fixe euro 60000 NA"),
                   c("incapacite ij_en_vigueur euro_par_jour NA hors_domaine", "ensemble ij_en_vigueur euro_par_jour NA hors_domaine")))
# (g) garantie d'une ligne porteuse (prestation PR3 de DO2, garantie GS3) dont le code est refusé
# de portée ligne : non_rattache (la valeur refusée n'est pas lue pour la rangée par garantie) ;
# écart hors_domaine sur prestations.nature_mouvement de PR3 (colonne que prestations_ecartees ne
# lit pas) : montant chiffré (750)
r72i <- cb(avec(function(b) { b$prestations$nature_mouvement[3L] <- "zzz"; b$garanties_souscrites$code_garantie[3L] <- "autre"; b }))
verifier_egal("#72, enjeu (g) : code_garantie de GS3 refusé, écart sur la nature de PR3 : prestations_ecartees de PR3 rangé non_rattache, chiffré (750)",
