  body(g0) <- parse(text = sub("complexe <- ctx$retenu[[t]] & (forcer | complexe)", "complexe <- ctx$retenu[[t]] & forcer",
                               paste(deparse(body(g0), width.cutoff = 500L), collapse = "\n"), fixed = TRUE))[[1L]]
  env$.verdict_d07c <- g0
